INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_030_M5_S6', 'microstructure', '6', 'microstructure refers to the internal arrangement of cement paste, aggregates, pores, and interfaces that controls many concrete properties. In Hardened Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of microstructure within Concrete Technology, particularly where the Hardened Concrete module establishes its technical context.', 'SSD_COURSE_030_M5_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M6_S1', 'batching', '1', 'batching: Measuring concrete constituents in specified quantities before mixing. In Concrete Production and Quality Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of batching within Concrete Technology, particularly where the Concrete Production and Quality Control module establishes its technical context.', 'SSD_COURSE_030_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M6_S2', 'mixing', '2', 'mixing: Combining concrete constituents until a sufficiently uniform mixture is obtained. In Concrete Production and Quality Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of mixing within Concrete Technology, particularly where the Concrete Production and Quality Control module establishes its technical context.', 'SSD_COURSE_030_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M6_S3', 'transport', '3', 'transport: Moving fresh concrete from the mixer to the placing location while limiting segregation and loss of workability. In Concrete Production and Quality Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of transport within Concrete Technology, particularly where the Concrete Production and Quality Control module establishes its technical context.', 'SSD_COURSE_030_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M6_S4', 'sampling', '4', 'sampling: Obtaining representative concrete samples for testing and quality-control decisions. In Concrete Production and Quality Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of sampling within Concrete Technology, particularly where the Concrete Production and Quality Control module establishes its technical context.', 'SSD_COURSE_030_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M6_S5', 'statistical quality control', '5', 'statistical quality control: Use of control charts, process statistics, sampling, and acceptance criteria to monitor concrete production consistency and detect significant variation. In Concrete Production and Quality Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of statistical quality control within Concrete Technology, particularly where the Concrete Production and Quality Control module establishes its technical context.', 'SSD_COURSE_030_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M7_S1', 'freeze-thaw', '1', 'freeze-thaw: Deterioration caused by repeated freezing and thawing of water within concrete pores. In Durability and Special Concretes, the focus is on the analysis, design, implementation, interpretation, or evaluation of freeze-thaw within Concrete Technology, particularly where the Durability and Special Concretes module establishes its technical context.', 'SSD_COURSE_030_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M7_S2', 'chloride ingress', '2', 'chloride ingress: Movement of chloride ions into concrete, potentially leading to corrosion of embedded steel reinforcement. In Durability and Special Concretes, the focus is on the analysis, design, implementation, interpretation, or evaluation of chloride ingress within Concrete Technology, particularly where the Durability and Special Concretes module establishes its technical context.', 'SSD_COURSE_030_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M7_S3', 'sulfate attack', '3', 'sulfate attack: Deterioration caused by reactions between sulfate-bearing environments and cementitious constituents in concrete. In Durability and Special Concretes, the focus is on the analysis, design, implementation, interpretation, or evaluation of sulfate attack within Concrete Technology, particularly where the Durability and Special Concretes module establishes its technical context.', 'SSD_COURSE_030_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M7_S4', 'alkali-silica reaction', '4', 'alkali-silica reaction refers to a deleterious reaction between reactive silica in aggregate and alkalis in cementitious pore solution that can produce expansive gel and concrete cracking. In Durability and Special Concretes, the focus is on the analysis, design, implementation, interpretation, or evaluation of alkali-silica reaction within Concrete Technology, particularly where the Durability and Special Concretes module establishes its technical context.', 'SSD_COURSE_030_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M7_S5', 'high-performance and fiber-reinforced concrete', '5', 'high-performance and fiber-reinforced concrete: Concrete designed for enhanced mechanical or durability performance, with fibres used to improve properties such as crack control, toughness, or post-cracking behaviour. In Durability and Special Concretes, the focus is on the analysis, design, implementation, interpretation, or evaluation of high-performance and fiber-reinforced concrete within Concrete Technology, particularly where the Durability and Special Concretes module establishes its technical context.', 'SSD_COURSE_030_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M1_S1', 'borings', '1', 'borings: Boreholes made during site investigation to determine subsurface strata, groundwater conditions, and obtain samples or test data. In Site Investigation and Subsurface Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of borings within Foundation Engineering, particularly where the Site Investigation and Subsurface Characterization module establishes its technical context.', 'SSD_COURSE_031_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M1_S2', 'Geotechnical sampling', '2', 'Geotechnical sampling: Collection of representative soil, rock, groundwater, or other subsurface samples for laboratory characterization and design decisions, with attention to sample disturbance and representativeness. In Site Investigation and Subsurface Characterization, the focus is on curricular scope: Foundation Engineering; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_031_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M1_S3', 'in-situ testing', '3', 'in-situ testing: Field testing of soil or ground conditions at their natural location to estimate engineering properties used in site characterization and foundation design. In Site Investigation and Subsurface Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of in-situ testing within Foundation Engineering, particularly where the Site Investigation and Subsurface Characterization module establishes its technical context.', 'SSD_COURSE_031_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M1_S4', 'groundwater', '4', 'groundwater: Water occupying the saturated zone beneath the ground surface and stored or transmitted through soil and rock formations. In Site Investigation and Subsurface Characterization, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_031_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M1_S5', 'stratigraphy', '5', 'stratigraphy refers to the sequence, thickness, and characteristics of soil or rock layers at a site. In Site Investigation and Subsurface Characterization, the focus is on the analysis, design, implementation, interpretation, or evaluation of stratigraphy within Foundation Engineering, particularly where the Site Investigation and Subsurface Characterization module establishes its technical context.', 'SSD_COURSE_031_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M2_S1', 'unit weight', '1', 'unit weight: Weight per unit volume of soil, used in stress, bearing-capacity, and earth-pressure calculations. In Soil Parameters for Foundation Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of unit weight within Foundation Engineering, particularly where the Soil Parameters for Foundation Design module establishes its technical context.', 'SSD_COURSE_031_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M2_S2', 'shear strength', '2', 'shear strength refers to the resistance of soil to shearing, commonly represented using cohesion and friction parameters. In Soil Parameters for Foundation Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of shear strength within Foundation Engineering, particularly where the Soil Parameters for Foundation Design module establishes its technical context.', 'SSD_COURSE_031_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M2_S3', 'compressibility', '3', 'compressibility refers to the tendency of soil to deform as effective stress increases, producing settlement. In Soil Parameters for Foundation Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of compressibility within Foundation Engineering, particularly where the Soil Parameters for Foundation Design module establishes its technical context.', 'SSD_COURSE_031_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M2_S4', 'Soil permeability', '4', 'Soil permeability: Property describing the ability of soil to transmit fluid through its interconnected pore space under a hydraulic gradient; commonly represented by hydraulic conductivity in saturated flow analysis. In Soil Parameters for Foundation Design, the focus is on curricular scope: Foundation Engineering; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_031_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M2_S5', 'stiffness', '5', 'stiffness refers to the resistance of soil to deformation under applied loading. In Soil Parameters for Foundation Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of stiffness within Foundation Engineering, particularly where the Soil Parameters for Foundation Design module establishes its technical context.', 'SSD_COURSE_031_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M3_S1', 'isolated footings', '1', 'isolated footings: Shallow foundations supporting individual columns and transferring their loads to the soil. In Shallow Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of isolated footings within Foundation Engineering, particularly where the Shallow Foundations module establishes its technical context.', 'SSD_COURSE_031_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M3_S2', 'strip footings', '2', 'strip footings: Continuous shallow foundations supporting walls or closely spaced columns. In Shallow Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of strip footings within Foundation Engineering, particularly where the Shallow Foundations module establishes its technical context.', 'SSD_COURSE_031_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M3_S3', 'combined footings', '3', 'combined footings refers to a footing designed to support two or more columns when geometry or loading makes separate footings unsuitable. In Shallow Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of combined footings within Foundation Engineering, particularly where the Shallow Foundations module establishes its technical context.', 'SSD_COURSE_031_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M3_S4', 'raft foundations', '4', 'raft foundations: Large slab-like foundations supporting many columns or walls and distributing loads over a broad soil area. In Shallow Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of raft foundations within Foundation Engineering, particularly where the Shallow Foundations module establishes its technical context.', 'SSD_COURSE_031_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M3_S5', 'load transfer', '5', 'load transfer refers to the transfer of structural loads through the foundation into the supporting soil or rock. In Shallow Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of load transfer within Foundation Engineering, particularly where the Shallow Foundations module establishes its technical context.', 'SSD_COURSE_031_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M4_S1', 'Terzaghi theory', '1', 'Terzaghi theory: Classical bearing-capacity theory for shallow foundations based on soil strength, footing geometry, and surcharge. In Bearing Capacity, the focus is on the analysis, design, implementation, interpretation, or evaluation of Terzaghi theory within Foundation Engineering, particularly where the Bearing Capacity module establishes its technical context.', 'SSD_COURSE_031_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M4_S2', 'Meyerhof methods', '2', 'Meyerhof methods: Bearing-capacity and foundation-design methods that account for factors such as footing shape, depth, inclination, and loading. In Bearing Capacity, the focus is on the analysis, design, implementation, interpretation, or evaluation of Meyerhof methods within Foundation Engineering, particularly where the Bearing Capacity module establishes its technical context.', 'SSD_COURSE_031_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M4_S3', 'Vesic concepts', '3', 'Vesic concepts: Bearing-capacity formulations and correction factors associated with Vesic''s foundation analysis. In Bearing Capacity, the focus is on the analysis, design, implementation, interpretation, or evaluation of Vesic concepts within Foundation Engineering, particularly where the Bearing Capacity module establishes its technical context.', 'SSD_COURSE_031_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M4_S4', 'eccentric loading', '4', 'eccentric loading: Foundation loading in which the resultant force does not pass through the centroid of the footing area. In Bearing Capacity, the focus is on the analysis, design, implementation, interpretation, or evaluation of eccentric loading within Foundation Engineering, particularly where the Bearing Capacity module establishes its technical context.', 'SSD_COURSE_031_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M4_S5', 'inclined loads', '5', 'inclined loads: Foundation loads having horizontal as well as vertical components. In Bearing Capacity, the focus is on the analysis, design, implementation, interpretation, or evaluation of inclined loads within Foundation Engineering, particularly where the Bearing Capacity module establishes its technical context.', 'SSD_COURSE_031_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M5_S1', 'immediate settlement', '1', 'immediate settlement: Settlement that occurs essentially during or soon after loading due to soil deformation without significant consolidation. In Settlement Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of immediate settlement within Foundation Engineering, particularly where the Settlement Analysis module establishes its technical context.', 'SSD_COURSE_031_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M5_S2', 'consolidation settlement', '2', 'consolidation settlement: Time-dependent settlement of a saturated or nearly saturated soil caused by dissipation of excess pore-water pressure and associated volume change under sustained loading. In Settlement Analysis, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_031_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M5_S3', 'differential settlement', '3', 'differential settlement: Unequal settlement between different parts of a foundation or structure. In Settlement Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of differential settlement within Foundation Engineering, particularly where the Settlement Analysis module establishes its technical context.', 'SSD_COURSE_031_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M5_S4', 'time-rate effects', '4', 'time-rate effects refers to the rate at which consolidation and other time-dependent soil deformation develop after loading. In Settlement Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of time-rate effects within Foundation Engineering, particularly where the Settlement Analysis module establishes its technical context.', 'SSD_COURSE_031_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M6_S1', 'piles', '1', 'piles: Deep foundation elements that transfer structural loads through shaft resistance, end bearing, or both. In Deep Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of piles within Foundation Engineering, particularly where the Deep Foundations module establishes its technical context.', 'SSD_COURSE_031_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M6_S2', 'pile capacity', '2', 'pile capacity refers to the load a pile can safely support based on geotechnical resistance and applicable serviceability limits. In Deep Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of pile capacity within Foundation Engineering, particularly where the Deep Foundations module establishes its technical context.', 'SSD_COURSE_031_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M6_S3', 'group action', '3', 'group action refers to the interaction among closely spaced piles that changes the load capacity and settlement of the pile group. In Deep Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of group action within Foundation Engineering, particularly where the Deep Foundations module establishes its technical context.', 'SSD_COURSE_031_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M6_S4', 'negative skin friction', '4', 'negative skin friction: Downward shear resistance acting on a pile when surrounding soil settles relative to the pile. In Deep Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of negative skin friction within Foundation Engineering, particularly where the Deep Foundations module establishes its technical context.', 'SSD_COURSE_031_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M6_S5', 'pile load testing', '5', 'pile load testing: Field testing used to assess the load–displacement behaviour and, where applicable, capacity of piles under axial or lateral loading. In Deep Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of pile load testing within Foundation Engineering, particularly where the Deep Foundations module establishes its technical context.', 'SSD_COURSE_031_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M7_S1', 'serviceability', '1', 'serviceability: Assessment of foundation performance against excessive settlement, rotation, vibration, or other unacceptable movement. In Foundation Design and Construction, the focus is on the analysis, design, implementation, interpretation, or evaluation of serviceability within Foundation Engineering, particularly where the Foundation Design and Construction module establishes its technical context.', 'SSD_COURSE_031_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M7_S2', 'structural checks', '2', 'structural checks: Verification that foundation elements have adequate strength and detailing for applied structural actions. In Foundation Design and Construction, the focus is on the analysis, design, implementation, interpretation, or evaluation of structural checks within Foundation Engineering, particularly where the Foundation Design and Construction module establishes its technical context.', 'SSD_COURSE_031_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M7_S3', 'ground improvement', '3', 'ground improvement: Methods used to increase soil strength, stiffness, drainage, or bearing performance before construction. In Foundation Design and Construction, the focus is on the analysis, design, implementation, interpretation, or evaluation of ground improvement within Foundation Engineering, particularly where the Foundation Design and Construction module establishes its technical context.', 'SSD_COURSE_031_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_031_M7_S4', 'construction monitoring', '4', 'construction monitoring: Field observation and measurement used to verify foundation behaviour and detect unexpected ground response during construction. In Foundation Design and Construction, the focus is on the analysis, design, implementation, interpretation, or evaluation of construction monitoring within Foundation Engineering, particularly where the Foundation Design and Construction module establishes its technical context.', 'SSD_COURSE_031_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M1_S1', 'precipitation', '1', 'precipitation: Water falling to the Earth''s surface as rain, snow, sleet, or other forms of atmospheric precipitation. In Hydrologic Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of precipitation within Water Resources Engineering, particularly where the Hydrologic Processes module establishes its technical context.', 'SSD_COURSE_032_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M1_S2', 'infiltration', '2', 'infiltration: Entry of water from the ground surface into the soil. In Hydrologic Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of infiltration within Water Resources Engineering, particularly where the Hydrologic Processes module establishes its technical context.', 'SSD_COURSE_032_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M1_S3', 'evaporation', '3', 'evaporation: Conversion of liquid water at a surface into water vapour. In Hydrologic Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of evaporation within Water Resources Engineering, particularly where the Hydrologic Processes module establishes its technical context.', 'SSD_COURSE_032_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M1_S4', 'interception', '4', 'interception: Temporary capture of precipitation by vegetation, structures, or other surfaces before it reaches the ground. In Hydrologic Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of interception within Water Resources Engineering, particularly where the Hydrologic Processes module establishes its technical context.', 'SSD_COURSE_032_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M1_S5', 'runoff', '5', 'runoff: Part of precipitation that flows over the land surface or through drainage pathways toward streams and water bodies. In Hydrologic Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of runoff within Water Resources Engineering, particularly where the Hydrologic Processes module establishes its technical context.', 'SSD_COURSE_032_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M1_S6', 'watershed processes', '6', 'watershed processes: Hydrological processes controlling the movement and storage of water within a drainage basin. In Hydrologic Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of watershed processes within Water Resources Engineering, particularly where the Hydrologic Processes module establishes its technical context.', 'SSD_COURSE_032_M1_S6', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;